const ocean=Color(0xff087eb1), cyan=Color(0xff16a9cf);
Color hex(dynamic x,Color fallback){if(x is String&&RegExp(r'^#[0-9a-fA-F]{6}$').hasMatch(x))return Color(int.parse('ff${x.substring(1)}',radix:16));return fallback;}
Color contrast(Color c){for(var i=0;i<20&&1.05/(c.computeLuminance()+.05)<4.5;i++){c=Color.lerp(c,const Color(0xff061d31),.15)!;}return c;}
class Brand {
 final String name,slug,kind;final Color primary,accent;final String? logo;
 const Brand({this.name='IDCOLDA',this.slug='',this.kind='Solar distribution',this.primary=ocean,this.accent=cyan,this.logo});
 factory Brand.from(dynamic x){final m=obj(x);return Brand(name:m['name']?.toString()??'IDCOLDA',slug:m['slug']?.toString()??'',kind:m['companyKind']?.toString()??'Solar distribution',primary:hex(m['primaryColor'],ocean),accent:hex(m['accentColor'],cyan),logo:m['logoUrl']?.toString()??(m['hasLogo']==true&&m['slug']!=null?'/company/${m['slug']}/logo':null));}
 Color get deep=>contrast(primary);
 String get initials=>name.trim().split(RegExp(r'\s+')).where((s)=>s.isNotEmpty).take(2).map((s)=>s[0].toUpperCase()).join();
}
ThemeData tide(Brand b,bool dark){final scheme=ColorScheme.fromSeed(seedColor:b.primary,brightness:dark?Brightness.dark:Brightness.light).copyWith(primary:dark?Color.lerp(b.accent,const Color(0xffe9faff),.55)!:b.deep,onPrimary:dark?const Color(0xff071d29):Colors.white,surface:dark?const Color(0xff103447):Colors.white,onSurface:dark?const Color(0xffe9faff):const Color(0xff15384a),outline:dark?const Color(0xff38677e):const Color(0xffbfdff0));return ThemeData(useMaterial3:true,colorScheme:scheme,scaffoldBackgroundColor:dark?const Color(0xff071d29):const Color(0xffe9f8ff),inputDecorationTheme:InputDecorationTheme(filled:true,fillColor:dark?const Color(0xff123b4f):const Color(0xfff2fbff),border:OutlineInputBorder(borderRadius:BorderRadius.circular(17),borderSide:BorderSide(color:scheme.outline)),enabledBorder:OutlineInputBorder(borderRadius:BorderRadius.circular(17),borderSide:BorderSide(color:scheme.outline)),focusedBorder:OutlineInputBorder(borderRadius:BorderRadius.circular(17),borderSide:BorderSide(color:scheme.primary,width:1.7)),contentPadding:const EdgeInsets.symmetric(horizontal:16,vertical:18)),filledButtonTheme:FilledButtonThemeData(style:FilledButton.styleFrom(minimumSize:const Size(0,52),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(19)))),cardTheme:CardThemeData(color:scheme.surface,elevation:0,margin:EdgeInsets.zero,shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(22),side:BorderSide(color:scheme.outline))),appBarTheme:AppBarTheme(backgroundColor:scheme.surface,surfaceTintColor:Colors.transparent,centerTitle:false,titleTextStyle:TextStyle(color:scheme.onSurface,fontSize:18,fontWeight:FontWeight.w800)),bottomSheetTheme:BottomSheetThemeData(backgroundColor:scheme.surface,surfaceTintColor:Colors.transparent,shape:const RoundedRectangleBorder(borderRadius:BorderRadius.vertical(top:Radius.circular(32)))),dialogTheme:DialogThemeData(backgroundColor:scheme.surface,shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(28))),snackBarTheme:SnackBarThemeData(behavior:SnackBarBehavior.floating,shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(18))),textTheme:const TextTheme(headlineLarge:TextStyle(fontSize:32,fontWeight:FontWeight.w900,letterSpacing:-.9,height:1.12),headlineMedium:TextStyle(fontSize:27,fontWeight:FontWeight.w800,letterSpacing:-.6,height:1.18),headlineSmall:TextStyle(fontSize:23,fontWeight:FontWeight.w800,height:1.22),titleLarge:TextStyle(fontSize:20,fontWeight:FontWeight.w800,letterSpacing:-.3,height:1.3),titleMedium:TextStyle(fontSize:16,fontWeight:FontWeight.w700,height:1.35),titleSmall:TextStyle(fontSize:14,fontWeight:FontWeight.w700,height:1.4),bodyLarge:TextStyle(fontSize:16,height:1.48),bodyMedium:TextStyle(fontSize:14,height:1.45),bodySmall:TextStyle(fontSize:12,height:1.45),labelMedium:TextStyle(fontSize:12,fontWeight:FontWeight.w600,letterSpacing:.15)));}
class FlowCanvas extends StatelessWidget {final Brand brand;final Widget child;final bool dark;const FlowCanvas({super.key,required this.brand,required this.child,required this.dark});@override Widget build(BuildContext c)=>Stack(fit:StackFit.expand,children:[CustomPaint(painter:WavePainter(brand,dark)),child]);}
class WavePainter extends CustomPainter{final Brand b;final bool dark;WavePainter(this.b,this.dark);@override void paint(Canvas c,Size s){final p=Paint()..color=b.accent.withValues(alpha:dark ? .08 : .17);c.drawPath(Path()..moveTo(0,0)..lineTo(s.width,0)..lineTo(s.width,s.height*.15)..cubicTo(s.width*.7,s.height*.29,s.width*.28,s.height*.02,0,s.height*.18)..close(),p);p.color=b.primary.withValues(alpha:dark ? .045 : .09);c.drawPath(Path()..moveTo(0,s.height*.85)..cubicTo(s.width*.35,s.height*.55,s.width*.62,s.height*.99,s.width,s.height*.75)..lineTo(s.width,s.height)..lineTo(0,s.height)..close(),p);}@override bool shouldRepaint(WavePainter old)=>old.b!=b||old.dark!=dark;}
class SolarArt extends StatefulWidget{final double size;const SolarArt({super.key,this.size=180});@override State<SolarArt> createState()=>_SolarArtState();}
class _SolarArtState extends State<SolarArt> with SingleTickerProviderStateMixin{late final AnimationController a=AnimationController(vsync:this,duration:const Duration(seconds:4))..repeat();@override void dispose(){a.dispose();super.dispose();}@override Widget build(BuildContext c){final reduced=MediaQuery.disableAnimationsOf(c);return AnimatedBuilder(animation:a,builder:(c,child)=>Transform.translate(offset:Offset(0,reduced?0:math.sin(a.value*math.pi*2)*6),child:child),child:Image.asset('assets/solar_network.png',width:widget.size,height:widget.size,fit:BoxFit.contain,semanticLabel:'Solar panels, warehouse and distribution network'));}}
class HeroCard extends StatelessWidget{final Brand brand;final String title,subtitle,tag;final VoidCallback? onTap;const HeroCard({super.key,required this.brand,required this.title,required this.subtitle,this.tag='SOLAR TIDE',this.onTap});@override Widget build(BuildContext c)=>ClipRRect(borderRadius:BorderRadius.circular(24),child:DecoratedBox(decoration:BoxDecoration(gradient:LinearGradient(colors:[brand.deep,Color.lerp(brand.primary,brand.accent,.45)!]),boxShadow:[BoxShadow(color:brand.primary.withValues(alpha:.16),blurRadius:20,offset:const Offset(0,8))]),child:Stack(children:[Positioned(right:-32,bottom:-20,child:Opacity(opacity:.88,child:SolarArt(size:190))),Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[CopyText(tag,style:const TextStyle(color:Colors.white,fontSize:11,fontWeight:FontWeight.w800,letterSpacing:1.5)),const SizedBox(height:12),FractionallySizedBox(widthFactor:.67,child:CopyText(title,style:const TextStyle(color:Colors.white,fontSize:27,fontWeight:FontWeight.w900,height:1.04))),const SizedBox(height:10),FractionallySizedBox(widthFactor:.63,child:CopyText(subtitle,style:const TextStyle(color:Colors.white,fontSize:13))),if(onTap!=null)TextButton(onPressed:onTap,style:TextButton.styleFrom(foregroundColor:Colors.white,padding:EdgeInsets.zero),child:const CopyText('View operations  →',style:TextStyle(fontWeight:FontWeight.w800))) ]))])));}
